import React, { useState, useEffect } from 'react';
import { useApprovalStore, ApprovalMode, getRiskLevelIcon, getRiskLevelColor, getApprovalModeIcon, getApprovalModeColor, getApprovalModeLabel, getApprovalModeDescription } from '../stores/approvalStore';

interface ApproveModeDialogProps {
  onClose: () => void;
}

// Approve modes matching TUI and backend
const APPROVE_MODES: Array<{ id: ApprovalMode; icon: string; color: string }> = [
  {
    id: 'ask',
    icon: '❓',
    color: 'text-gray-500',
  },
  {
    id: 'auto',
    icon: '⚡',
    color: 'text-green-600',
  },
  {
    id: 'strict',
    icon: '🔒',
    color: 'text-red-600',
  },
];

export function ApproveModeDialog({ onClose }: ApproveModeDialogProps) {
  const [selectedMode, setSelectedMode] = useState<ApprovalMode | null>(null);
  const [showHistory, setShowHistory] = useState(false);

  // Approval store state
  const mode = useApprovalStore((s) => s.mode);
  const pendingApprovals = useApprovalStore((s) => s.pendingApprovals);
  const approvalHistory = useApprovalStore((s) => s.approvalHistory);
  const stats = useApprovalStore((s) => s.stats);
  const currentApproval = useApprovalStore((s) => s.currentApproval);
  const loading = useApprovalStore((s) => s.loading);

  // Approval store actions
  const setMode = useApprovalStore((s) => s.setMode);
  const approve = useApprovalStore((s) => s.approve);
  const reject = useApprovalStore((s) => s.reject);
  const abort = useApprovalStore((s) => s.abort);
  const loadHistory = useApprovalStore((s) => s.loadHistory);
  const setCurrentApproval = useApprovalStore((s) => s.setCurrentApproval);
  const startListening = useApprovalStore((s) => s.startListening);
  const stopListening = useApprovalStore((s) => s.stopListening);

  // Load history and start listening on mount
  useEffect(() => {
    loadHistory();
    startListening();
    return () => stopListening();
  }, [loadHistory, startListening, stopListening]);

  // Handle mode selection
  const handleSelectMode = async (modeId: ApprovalMode) => {
    setSelectedMode(modeId);
    try {
      await setMode(modeId);
      console.log(`Approve mode changed to: ${modeId}`);
    } catch (e) {
      console.error('Failed to update approve mode:', e);
    }
  };

  // Handle approve action
  const handleApprove = async (id: string) => {
    await approve(id);
  };

  // Handle reject action
  const handleReject = async (id: string, reason?: string) => {
    await reject(id, reason);
  };

  // Handle abort
  const handleAbort = async () => {
    await abort();
    onClose();
  };

  // Get icon element based on icon name
  const getIconElement = (iconName: string, className?: string): React.ReactNode => {
    const iconClass = className || 'w-5 h-5';
    // iconName is now emoji, just return it directly
    return <span className={iconClass}>{iconName}</span>;
  };

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
      <div className="bg-card border shadow-lg rounded-lg max-w-2xl w-full overflow-hidden max-h-[80vh] flex flex-col">
        {/* Header */}
        <div className="p-4 border-b bg-muted/30">
          <div className="flex items-center justify-between">
            <h3 className="text-lg font-semibold flex items-center gap-2">
              <span aria-hidden="true">⚡</span>
              <span>批准模式</span>
            </h3>
            <button
              onClick={onClose}
              className="text-muted-foreground hover:text-foreground p-1 rounded hover:bg-accent transition-colors"
              aria-label="关闭对话框"
            >
              ✕
            </button>
          </div>
          <p className="text-sm text-muted-foreground mt-1">
            选择 Agent 执行操作的批准模式
          </p>
        </div>

        {/* Current mode indicator */}
        <div className="px-4 py-2 bg-muted/20 border-b">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2 text-xs">
              <span className="text-muted-foreground">当前模式:</span>
              <span className={`px-2 py-0.5 rounded font-mono ${getApprovalModeColor(mode)}`}>
                {getIconElement(getApprovalModeIcon(mode))} {getApprovalModeLabel(mode)}
              </span>
            </div>
            {/* Statistics summary */}
            <div className="flex items-center gap-2 text-xs text-muted-foreground">
              <span>统计: 批准 {stats.approved} | 拒绝 {stats.rejected} | 自动 {stats.autoApproved}</span>
            </div>
          </div>
        </div>

        {/* Pending approvals queue */}
        {pendingApprovals.length > 0 && (
          <div className="px-4 py-3 border-b bg-yellow-50/10">
            <div className="flex items-center justify-between mb-2">
              <div className="flex items-center gap-2">
                <span className="text-sm font-medium">待批准操作</span>
                <span className="px-2 py-0.5 bg-yellow-100 text-yellow-800 text-xs rounded-full">
                  {pendingApprovals.length} 个
                </span>
              </div>
              <button
                onClick={handleAbort}
                className="px-2 py-1 text-xs bg-red-100 text-red-600 rounded hover:bg-red-200 transition-colors"
              >
                中止本轮
              </button>
            </div>

            {/* Current approval request */}
            {currentApproval && (
              <div className="bg-card border rounded-lg p-3 mb-2">
                <div className="flex items-start gap-2">
                  <span className={`text-lg ${getRiskLevelColor(currentApproval.risk_level)}`}>
                    {getIconElement(getRiskLevelIcon(currentApproval.risk_level))}
                  </span>
                  <div className="flex-1">
                    <div className="text-sm font-medium">{currentApproval.summary}</div>
                    <div className="text-xs text-muted-foreground mt-1">
                      工具: {currentApproval.tool_name} | 风险: {currentApproval.risk_level}
                    </div>
                    {currentApproval.input && (
                      <div className="mt-2 bg-muted/30 rounded p-2 text-xs font-mono overflow-x-auto">
                        <pre className="text-xs">{JSON.stringify(currentApproval.input, null, 2)}</pre>
                      </div>
                    )}
                  </div>
                </div>

                {/* Approval actions */}
                <div className="flex gap-2 mt-3">
                  <button
                    onClick={() => handleApprove(currentApproval.id)}
                    disabled={loading}
                    className="flex-1 px-3 py-2 bg-green-600 text-white rounded-lg text-sm hover:bg-green-700 transition-colors disabled:opacity-50"
                  >
                    执行
                  </button>
                  <button
                    onClick={() => handleReject(currentApproval.id)}
                    disabled={loading}
                    className="flex-1 px-3 py-2 bg-muted text-muted-foreground rounded-lg text-sm hover:bg-accent transition-colors disabled:opacity-50"
                  >
                    跳过
                  </button>
                </div>
              </div>
            )}

            {/* Queue items (other pending requests) */}
            {pendingApprovals.filter(r => r.id !== currentApproval?.id).length > 0 && (
              <div className="space-y-1">
                <div className="text-xs text-muted-foreground mb-1">队列中:</div>
                {pendingApprovals
                  .filter(r => r.id !== currentApproval?.id)
                  .map((request, idx) => (
                    <div
                      key={request.id}
                      onClick={() => setCurrentApproval(request)}
                      className="flex items-center gap-2 p-2 bg-muted/30 rounded cursor-pointer hover:bg-accent/50 transition-colors"
                    >
                      <span className={`text-sm ${getRiskLevelColor(request.risk_level)}`}>
                        {getIconElement(getRiskLevelIcon(request.risk_level))}
                      </span>
                      <span className="text-xs truncate">{request.summary}</span>
                      <span className="text-xs text-muted-foreground ml-auto">#{idx + 2}</span>
                    </div>
                  ))}
              </div>
            )}
          </div>
        )}

        {/* Tab switcher */}
        <div className="flex border-b">
          <button
            onClick={() => setShowHistory(false)}
            className={`flex-1 px-4 py-2 text-sm transition-colors ${
              !showHistory
                ? 'bg-card border-b-2 border-primary font-medium'
                : 'text-muted-foreground hover:text-foreground'
            }`}
          >
            模式选择
          </button>
          <button
            onClick={() => setShowHistory(true)}
            className={`flex-1 px-4 py-2 text-sm transition-colors ${
              showHistory
                ? 'bg-card border-b-2 border-primary font-medium'
                : 'text-muted-foreground hover:text-foreground'
            }`}
          >
            历史记录 ({stats.total})
          </button>
        </div>

        {/* Content area */}
        <div className="flex-1 overflow-y-auto">
          {!showHistory ? (
            /* Mode selection panel */
            <div className="p-4 space-y-3">
              {APPROVE_MODES.map((modeOption) => (
                <button
                  key={modeOption.id}
                  onClick={() => handleSelectMode(modeOption.id)}
                  disabled={selectedMode !== null || loading}
                  className={`w-full p-4 rounded-lg border transition-all ${
                    mode === modeOption.id
                      ? 'border-primary bg-primary/10'
                      : 'border-border hover:border-primary/50 hover:bg-accent/30'
                  } ${selectedMode === modeOption.id ? 'animate-pulse' : ''} ${
                    loading ? 'opacity-50 cursor-not-allowed' : ''
                  }`}
                >
                  <div className="flex items-start gap-3">
                    <span className={`text-2xl ${modeOption.color}`}>
                      {getIconElement(modeOption.icon)}
                    </span>
                    <div className="flex-1">
                      <div className="flex items-center gap-2">
                        <span className="font-semibold">{getApprovalModeLabel(modeOption.id)}</span>
                        {mode === modeOption.id && (
                          <span className="px-1.5 py-0.5 bg-primary text-primary-foreground text-xs rounded">
                            当前
                          </span>
                        )}
                      </div>
                      <p className="text-sm text-muted-foreground mt-1">
                        {getApprovalModeDescription(modeOption.id)}
                      </p>
                      <ul className="mt-2 space-y-1">
                        {modeOption.id === 'ask' && (
                          <>
                            <li className="text-xs text-muted-foreground flex items-center gap-1">
                              <span className="text-muted-foreground/50">•</span>
                              工具执行前询问
                            </li>
                            <li className="text-xs text-muted-foreground flex items-center gap-1">
                              <span className="text-muted-foreground/50">•</span>
                              文件修改前确认
                            </li>
                            <li className="text-xs text-muted-foreground flex items-center gap-1">
                              <span className="text-muted-foreground/50">•</span>
                              推荐用于敏感操作
                            </li>
                          </>
                        )}
                        {modeOption.id === 'auto' && (
                          <>
                            <li className="text-xs text-muted-foreground flex items-center gap-1">
                              <span className="text-muted-foreground/50">•</span>
                              读取操作自动执行
                            </li>
                            <li className="text-xs text-muted-foreground flex items-center gap-1">
                              <span className="text-muted-foreground/50">•</span>
                              写入操作自动执行
                            </li>
                            <li className="text-xs text-muted-foreground flex items-center gap-1">
                              <span className="text-muted-foreground/50">•</span>
                              推荐用于日常开发
                            </li>
                          </>
                        )}
                        {modeOption.id === 'strict' && (
                          <>
                            <li className="text-xs text-muted-foreground flex items-center gap-1">
                              <span className="text-muted-foreground/50">•</span>
                              所有操作需确认
                            </li>
                            <li className="text-xs text-muted-foreground flex items-center gap-1">
                              <span className="text-muted-foreground/50">•</span>
                              包括读取文件
                            </li>
                            <li className="text-xs text-muted-foreground flex items-center gap-1">
                              <span className="text-muted-foreground/50">•</span>
                              推荐用于生产环境
                            </li>
                          </>
                        )}
                      </ul>
                    </div>
                  </div>
                </button>
              ))}
            </div>
          ) : (
            /* History panel */
            <div className="p-4">
              {/* Statistics summary */}
              <div className="grid grid-cols-4 gap-2 mb-4">
                <div className="bg-green-50/10 border rounded-lg p-3 text-center">
                  <div className="text-lg font-semibold text-green-600">{stats.approved}</div>
                  <div className="text-xs text-muted-foreground">批准</div>
                </div>
                <div className="bg-red-50/10 border rounded-lg p-3 text-center">
                  <div className="text-lg font-semibold text-red-600">{stats.rejected}</div>
                  <div className="text-xs text-muted-foreground">拒绝</div>
                </div>
                <div className="bg-blue-50/10 border rounded-lg p-3 text-center">
                  <div className="text-lg font-semibold text-blue-600">{stats.autoApproved}</div>
                  <div className="text-xs text-muted-foreground">自动批准</div>
                </div>
                <div className="bg-orange-50/10 border rounded-lg p-3 text-center">
                  <div className="text-lg font-semibold text-orange-600">{stats.aborted}</div>
                  <div className="text-xs text-muted-foreground">中止</div>
                </div>
              </div>

              {/* History list */}
              {approvalHistory.length === 0 ? (
                <div className="text-center text-muted-foreground py-8">
                  <div className="text-4xl mb-2">📋</div>
                  <div className="text-sm">暂无批准历史记录</div>
                </div>
              ) : (
                <div className="space-y-2">
                  {approvalHistory.slice(-50).reverse().map((record) => (
                    <div
                      key={record.id}
                      className="bg-muted/30 border rounded-lg p-3"
                    >
                      <div className="flex items-start gap-2">
                        <span className={`text-lg ${getRiskLevelColor(record.request.risk_level)}`}>
                          {getIconElement(getRiskLevelIcon(record.request.risk_level))}
                        </span>
                        <div className="flex-1">
                          <div className="flex items-center gap-2">
                            <span className="text-sm font-medium truncate">
                              {record.request.summary}
                            </span>
                            {record.autoApproved && (
                              <span className="px-1.5 py-0.5 bg-blue-100 text-blue-600 text-xs rounded">
                                自动
                              </span>
                            )}
                            {record.answer === 'yes' && !record.autoApproved && (
                              <span className="px-1.5 py-0.5 bg-green-100 text-green-600 text-xs rounded">
                                执行
                              </span>
                            )}
                            {record.answer === 'no' && (
                              <span className="px-1.5 py-0.5 bg-red-100 text-red-600 text-xs rounded">
                                跳过
                              </span>
                            )}
                            {record.answer === 'abort' && (
                              <span className="px-1.5 py-0.5 bg-orange-100 text-orange-600 text-xs rounded">
                                中止
                              </span>
                            )}
                          </div>
                          <div className="text-xs text-muted-foreground mt-1">
                            工具: {record.request.tool_name} | 风险: {record.request.risk_level}
                          </div>
                          {record.reason && (
                            <div className="text-xs text-muted-foreground mt-1 italic">
                              原因: {record.reason}
                            </div>
                          )}
                          <div className="text-xs text-muted-foreground mt-1">
                            {new Date(record.timestamp).toLocaleString()}
                          </div>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="p-4 border-t bg-muted/30">
          <div className="flex gap-2">
            <button
              onClick={onClose}
              className="flex-1 px-4 py-2 bg-muted text-muted-foreground rounded-lg text-sm hover:bg-accent transition-colors"
            >
              关闭
            </button>
            <div className="flex-1 flex items-center justify-center text-xs text-muted-foreground">
              <kbd className="px-1.5 py-0.5 bg-muted rounded">Alt+M</kbd>
              <span className="ml-1">快捷切换</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}